<script lang="ts">
  import type { HTMLInputAttributes } from 'svelte/elements'; import type { OnValueChange } from '../shared/types.js'; import { composeEventHandlers } from '../shared/events.js'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; import { getComboboxContext } from './combobox-context.svelte.js';
  interface Props extends Omit<HTMLInputAttributes, 'value'> { onValueChange?: OnValueChange<string, 'input'>; ref?: HTMLInputElement | null; }
  let { onValueChange, ref = $bindable(null), oninput, onkeydown, onfocus, ...rest }: Props = $props(); const box = getComboboxContext(); const popover = getPopoverContext(); $effect.pre(() => { box.input = ref; if (!popover.trigger) popover.trigger = ref; });
  function input(event: Event) { const next = (event.currentTarget as HTMLInputElement).value; box.setInputValue(next, event); onValueChange?.(next, { reason: 'input', event }); popover.setOpen(true, 'trigger-press', event); const first = box.visibleItems[0]; box.highlightedId = first?.id ?? null; }
  function keydown(event: KeyboardEvent) { if (event.key === 'ArrowDown') { event.preventDefault(); if (!popover.open) popover.setOpen(true, 'trigger-press', event); box.move(1); } else if (event.key === 'ArrowUp') { event.preventDefault(); if (!popover.open) popover.setOpen(true, 'trigger-press', event); box.move(-1); } else if (event.key === 'Enter' && popover.open && box.highlightedItem) { event.preventDefault(); box.select(box.highlightedItem.value, 'keyboard', event); } else if (event.key === 'Escape') { event.preventDefault(); popover.setOpen(false, 'escape-key', event); } else if (event.key === 'Home' && popover.open) { box.highlightedId = box.visibleItems[0]?.id ?? null; } else if (event.key === 'End' && popover.open) { box.highlightedId = box.visibleItems.at(-1)?.id ?? null; } }
</script>
<input bind:this={ref} {...rest} id={box.inputId} role="combobox" aria-autocomplete="list" aria-expanded={popover.open} aria-controls={box.listId} aria-activedescendant={box.highlightedId ?? undefined} aria-labelledby={box.labelId} value={box.inputValue} disabled={box.disabled} readonly={box.readOnly} required={box.required} autocomplete="off" data-popup-open={popover.open ? '' : undefined} oninput={composeEventHandlers(oninput, input)} onkeydown={composeEventHandlers(onkeydown, keydown)} onfocus={composeEventHandlers(onfocus, (event) => { if (box.inputValue) popover.setOpen(true, 'trigger-press', event); })} />
